const update = $json.message ?? $json.edited_message ?? $json;
const chatId = update.chat?.id ?? update.from?.id;
const text = (update.text ?? update.caption ?? '').trim();
const voice = update.voice ?? update.audio;
const messageId = update.message_id;

return [{ json: {
  chatId,
  messageId,
  inputText: text,
  inputType: voice ? 'voice' : 'text',
  voiceFileId: voice?.file_id ?? null,
  voiceMimeType: voice?.mime_type ?? null,
  receivedAt: new Date().toISOString(),
  timezone: 'Asia/Kolkata',
  needsTranscription: Boolean(voice) && !text
}}];
